import json,sys,re,html,collections
from pathlib import Path
sys.path.insert(0,'/tmp/garden-reading-libs')
import markdown
B=Path(__file__).resolve().parent.parent;D=B/'詳細修訂版'
R=json.loads((B/'編輯資料/全題詳解內容.json').read_text())
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f5ef;color:#293b32;font-family:"Noto Sans CJK TC","Microsoft JhengHei",sans-serif;font-size:18px;line-height:1.95}button,input,select{font:inherit;color:inherit}button,select,input{border:1px solid #bfcbbb;border-radius:7px;background:#fffefa}button{padding:8px 13px;cursor:pointer}button:hover{background:#edf2e8}button:disabled{opacity:.4;cursor:default}aside{position:fixed;inset:0 auto 0 0;width:296px;background:#eaf0e5;border-right:1px solid #d1dccb;padding:24px 18px;overflow:auto;z-index:2}aside h1{font-size:23px;line-height:1.5;margin:10px 0 20px}.kicker{font-size:13px;letter-spacing:.11em;color:#65795e}label{display:block;font-size:14px;margin-top:12px;color:#4e684c}select,input{display:block;width:100%;padding:8px 10px;font-size:15px;margin:5px 0 10px}.selects{display:grid;grid-template-columns:1fr 90px;gap:10px}.selects label{margin:0}#resultCount,.note{font-size:14px;color:#65765e;line-height:1.8}nav{margin:18px 0}nav button{width:100%;text-align:left;margin:5px 0;font-size:14px;line-height:1.7;display:block;padding:9px 11px}nav button.active{background:#2d543c;color:white;border-color:#2d543c}nav small{display:block;opacity:.75;font-size:12px}.sideactions{display:flex;gap:8px;flex-wrap:wrap}.sideactions button{font-size:13px}main{margin-left:296px;padding:36px 48px 120px;max-width:1230px}.topline{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.topline a{font-size:14px}header{border-bottom:1px solid #d4ddcc;padding-bottom:20px;margin-bottom:28px}header h1{font-size:28px;line-height:1.5;margin:12px 0}.page{max-width:800px}.page h2{font-size:27px;color:#244c34;line-height:1.6;margin:20px 0 30px}.page h3{font-size:21px;line-height:1.7;border-left:4px solid #91a577;padding-left:13px;margin:40px 0 17px}.page p{margin:17px 0 24px}.page strong{color:#2c6340}.page p>strong:only-child{display:block;margin-top:24px}.page table{width:100%;border-collapse:collapse;font-size:16px;line-height:1.8;margin:24px 0;background:#fffefa}.page th{background:#e6eddd;text-align:left}.page th,.page td{padding:12px 14px;border:1px solid #d2dcc9;vertical-align:top}.page li{margin:12px 0}.page ul{padding-left:26px}a{color:#286747;overflow-wrap:anywhere}.page img{max-width:100%;height:auto;background:white;border:1px solid #dde4d5;border-radius:6px}.page blockquote{margin:20px 0;padding:10px 20px;background:#eef3e9;border-left:3px solid #9aaf83}footer{position:fixed;left:296px;right:0;bottom:0;display:flex;gap:10px;align-items:center;background:#fffdf7f5;padding:12px 30px;border-top:1px solid #d2dcc9;z-index:3}#counter{margin-left:auto;font-size:14px;color:#62735d}.exam-page{padding-bottom:50px;border-bottom:2px solid #cbd9c0;margin-bottom:40px}.empty{padding:40px;background:#edf2e7;border-radius:8px}.sectionnav{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:30px}.sectionnav a{font-size:13px;text-decoration:none;border:1px solid #ced9c6;border-radius:20px;padding:4px 11px;background:#fffefa}.sectionnav a:hover{background:#e5eeda}.status{font-size:13px;color:#6f8067}#mobileToggle{display:none}.modehint{font-size:14px;color:#66775e;padding:12px 16px;background:#edf2e6;border-radius:7px}body.exam footer #counter{font-size:13px}@media(max-width:900px){aside{position:static;width:auto;padding:16px;border-right:0;border-bottom:1px solid #ced9c5}aside h1{font-size:21px;margin:6px 0 12px}main{margin:0;padding:24px 20px 100px}footer{left:0;padding:10px 15px}body{font-size:17px}.page h2{font-size:24px}.page h3{font-size:20px}.page table{display:block;overflow-x:auto;font-size:14px}.page th,.page td{min-width:110px;padding:10px}header h1{font-size:24px}nav{max-height:230px;overflow:auto}.selects{grid-template-columns:1fr 110px}#mobileToggle{display:inline-block;font-size:14px}body.navclosed #sidebarControls{display:none}.page p{overflow-wrap:anywhere}#counter{font-size:12px}footer button{font-size:14px}aside .note{margin-bottom:0}}@media print{aside,footer,header,.sectionnav,.modehint{display:none!important}main{margin:0;padding:0;max-width:none}.page{display:block!important;max-width:none;break-before:page;border:0}.page:first-of-type{break-before:auto}body{background:white;color:#111;font-size:11pt;line-height:1.8}.page h2{font-size:18pt}.page h3{font-size:13pt;break-after:avoid}.page table{display:table;font-size:9pt}tr,img{break-inside:avoid}.page a{color:inherit;text-decoration:none}p{orphans:3;widows:3}}'''
JS='''const data=JSON.parse(document.getElementById('data').textContent);const $=id=>document.getElementById(id);let list=[],current=null,examMode=false;const subjectOrder=['果樹學','花卉學','蔬菜學','園藝植物學'];const subjects=subjectOrder.filter(s=>data.some(r=>r.s===s));subjects.forEach(s=>$('subject').add(new Option(s,s)));function setYears(prefer){const ys=[...new Set(data.filter(r=>r.s===$('subject').value).map(r=>r.y))].sort((a,b)=>b-a);$('year').replaceChildren();ys.forEach(y=>$('year').add(new Option(y+' 年',y)));if(prefer&&ys.includes(+prefer))$('year').value=prefer}function filter(wanted){const query=$('search').value.trim().toLowerCase();list=data.filter(r=>query?(r.search.includes(query)):(r.s===$('subject').value&&r.y===+$('year').value));$('resultCount').textContent=query?'搜尋結果 '+list.length+' 題（跨全部科目與年度）':'本卷 '+list.length+' 大題';$('nav').replaceChildren();list.forEach((r,i)=>{const b=document.createElement('button');b.dataset.id=r.id;b.innerHTML=(query?'<small>'+r.y+' 年 '+r.s+'</small>':'')+'第'+r.n+'題｜'+escapeHTML(r.t);b.onclick=()=>show(r.id);$('nav').append(b)});if(!list.length){current=null;$('content').innerHTML='<div class="empty">沒有符合的題目。可縮短關鍵字，或清除搜尋後選擇科目與年度。</div>';$('counter').textContent='0 題';$('prev').disabled=true;$('next').disabled=true;return}show(wanted&&list.some(r=>r.id===wanted)?wanted:list[0].id,false)}function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function prepareContent(){document.querySelectorAll('#content h3').forEach((h,i)=>h.id='section-'+i);if(!examMode){const hs=[...document.querySelectorAll('#content h3')];const links=hs.map(h=>'<a href="#'+h.id+'">'+escapeHTML(h.textContent.split('：')[0])+'</a>').join('');const el=document.createElement('div');el.className='sectionnav';el.innerHTML=links;$('content').prepend(el)}}function show(id,scroll=true){const r=data.find(x=>x.id===id);if(!r)return;current=r;examMode=false;document.body.classList.remove('exam');$('content').innerHTML='<article class="page">'+r.body+'</article>';prepareContent();$('examTitle').textContent=r.y+' 年 '+r.s;$('source').href=r.source;$('mdLink').href=r.md;$('source').hidden=false;$('mdLink').hidden=false;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.id===id));const i=list.findIndex(x=>x.id===id);$('counter').textContent=(i+1)+' / '+list.length;$('prev').disabled=i<=0;$('next').disabled=i>=list.length-1;history.replaceState(null,'','#q='+encodeURIComponent(id));if(scroll)window.scrollTo({top:window.innerWidth<=900?document.querySelector('main').offsetTop:0,behavior:'instant'});try{localStorage.setItem('garden-detail-last',id)}catch(e){}}function showExam(print=false){if(!current)return;const qs=data.filter(r=>r.s===current.s&&r.y===current.y);examMode=true;document.body.classList.add('exam');$('content').innerHTML='<p class="modehint">本卷全文模式：'+qs.length+' 大題。按左側題號可回到逐題閱讀。</p>'+qs.map(r=>'<article class="page exam-page">'+r.body+'</article>').join('');prepareContent();$('counter').textContent='本卷全文 · '+qs.length+' 題';$('prev').disabled=true;$('next').disabled=true;if(print)requestAnimationFrame(()=>window.print());else window.scrollTo(0,0)}$('subject').onchange=()=>{setYears();$('search').value='';filter()};$('year').onchange=()=>{$('search').value='';filter()};let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>filter(),160)};$('clear').onclick=()=>{$('search').value='';filter()};$('prev').onclick=()=>{const i=list.findIndex(r=>r.id===current.id);if(i>0)show(list[i-1].id)};$('next').onclick=()=>{const i=list.findIndex(r=>r.id===current.id);if(i<list.length-1)show(list[i+1].id)};$('all').onclick=()=>showExam();$('print').onclick=()=>showExam(true);$('mobileToggle').onclick=()=>document.body.classList.toggle('navclosed');document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'&&!$('next').disabled)$('next').click();if(e.key==='ArrowLeft'&&!$('prev').disabled)$('prev').click()});let initial;try{initial=decodeURIComponent(location.hash.replace(/^#q=/,''))}catch(e){}let r=data.find(x=>x.id===initial);if(!r)r=data.find(x=>x.s==='果樹學'&&x.y===111)||data[0];if(window.innerWidth<=900)document.body.classList.add('navclosed');$('subject').value=r.s;setYears(r.y);filter(r.id);$('content').addEventListener('click',e=>{const a=e.target.closest('.sectionnav a');if(a){e.preventDefault();document.getElementById(a.hash.slice(1)).scrollIntoView({behavior:'smooth'});}});window.reader={get current(){return current},get list(){return list},show,showExam,filter,data};'''

def build(rows,target,root=False):
 data=[]
 for r in rows:
  body=markdown.markdown(r['md'],extensions=['tables','sane_lists'])
  source=r['source'];md=f"{r['year']}年{r['subject']}_逐題教學詳解.md"
  if root:
   body=body.replace('href="../../','href="../').replace('src="../圖解/','src="圖解/')
   source=source.replace('../../','../');md='詳細修訂版/'+md
  data.append(dict(id=r['id'],s=r['subject'],y=r['year'],n=r['num'],t=r['title'],body=body,source=source,md=md,search=(r['title']+' '+r['md']+' '+str(r['year'])+' '+r['subject']).lower()))
 serialized=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
 title='園藝考古題｜全套逐題教學詳解' if root else f"{rows[0]['year']} 年{rows[0]['subject']}｜逐題教學詳解"
 fullLink='' if root else '<p><a href="../園藝考古題_逐題教學詳解.html">開啟全部科目與年度 →</a></p>'
 doc=f'''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{CSS}</style></head><body><aside><div class="kicker">逐題教學詳解 · 完整修訂</div><h1>園藝考古題<br>先理解，再練申論</h1><button id="mobileToggle">展開／收起選題</button><div id="sidebarControls"><div class="selects"><label>科目<select id="subject" aria-label="科目"></select></label><label>年度<select id="year" aria-label="年度"></select></label></div><label for="search">搜尋題目與內容</label><input id="search" type="search" placeholder="例：春化、缺鈣、111" autocomplete="off"><div class="sideactions"><button id="clear">清除搜尋</button><button id="all">本卷全文</button><button id="print">列印本卷</button></div><p id="resultCount" role="status"></p><nav id="nav" aria-label="題目清單"></nav><p class="note">配分重點是建議作答架構，<br>不是校方公布的評分細則。</p>{fullLink}</div></aside><main><header><div class="kicker">題意 → 原理 → 申論稿 → 實例 → 配分</div><h1 id="examTitle"></h1><div class="topline"><a id="source" target="_blank" rel="noopener">對照原始試卷 ↗</a><a id="mdLink">開啟本卷文字稿</a><span class="status">共 {len(rows)} 題 · 一次閱讀一題</span></div></header><div id="content"></div><noscript>此閱讀器需要 JavaScript 才能切題。請改開同目錄下的逐題教學詳解 Markdown 文字稿。</noscript></main><footer><button id="prev">← 上一題</button><button id="next">下一題 →</button><span id="counter" role="status"></span></footer><script id="data" type="application/json">{serialized}</script><script>{JS}</script></body></html>'''
 target.write_text(doc)

build(R,B/'園藝考古題_逐題教學詳解.html',True)
by=collections.defaultdict(list)
for r in R:by[r['subject'],r['year']].append(r)
for (s,y),rs in by.items():build(rs,D/f'{y}年{s}_逐題教學詳解.html')
print('readers',len(by)+1,'main bytes',(B/'園藝考古題_逐題教學詳解.html').stat().st_size)
